#!/usr/bin/env python3
# Ledger: P32 Stage 1 — EXPLORATORY model selection: can a compact description predict unmeasured, correction-specific responses at untouched cells?
# (plan Documentation/Note_2026-10-13_Rebuttal_P32_Plan.md, Stage 1 frozen before it runs). Attention 192; P26 (D training only, C) and P27 archives;
# hidden states regenerated by a bounded deterministic replay of their own pair construction (scratch output directory; provenance-checked).
"""Phases: `replay` (JAX environment: regenerate pairs, provenance gates, features per (state, condition, mask, evaluation cell) -> p32_features_*.npz)
and `analyze` (numpy: two-part ridge models B0 / B1 / B1o / M3 / M3o / M3b with identical probe calibration; puzzle-grouped outer and inner folds with
P26's discovery puzzles training-only; the primary within-dose target; the Stage-1 rule; the Stage-3 prototype on P27's hybrids)."""
import argparse, json, sys, time
from pathlib import Path
import numpy as np

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "tools"))
OUT = ROOT / "runs/analysis/rebuttal_20261018"
SCRATCH = OUT / "_replay_meta"
SEED = 20261018
WIDTH = 192
ARCH = {"P26D": ROOT / "runs/analysis/rebuttal_20261012/attention_192/p26_D.npz", "P26C": ROOT / "runs/analysis/rebuttal_20261012/attention_192/p26_C.npz",
        "P27": ROOT / "runs/analysis/rebuttal_20261013/attention_192/p27.npz"}
HYBRIDS = ("lead", "lead_ctrl", "full", "full_random", "comb_ctrl")
LAMBDAS, OUTER, INNER, NB, RMS_MIN, PROBE = (0.1, 1.0, 10.0, 100.0, 1000.0), 8, 4, 2000, 1e-4, 0
ND, NM, NE = 3, 4, 4                                        # doses, masks per dose, evaluation cells

# ---------------- Sudoku geometry ----------------
_r, _c = np.divmod(np.arange(81), 9); _b = (_r // 3) * 3 + _c // 3
ROW = (_r[:, None] == _r[None, :]); COL = (_c[:, None] == _c[None, :]); BOX = (_b[:, None] == _b[None, :]); np.fill_diagonal(ROW, False); np.fill_diagonal(COL, False); np.fill_diagonal(BOX, False)
REL = ROW | COL | BOX


def violations(g):
    G = np.asarray(g).reshape(9, 9); oh = (G[..., None] == np.arange(1, 10)); rows = oh.sum(1); cols = oh.sum(0); bx = oh.reshape(3, 3, 3, 3, 9).sum((1, 3)).reshape(9, 9)
    return int(sum(np.maximum(x - 1, 0).sum() for x in (rows, cols, bx)))


# feature block names (frozen; Stage 1)
B0_N = ["dose0", "dose1", "dose2", "n", "n_row", "n_col", "n_box", "n_rel", "n_unrel"]
B1_N = ["rel_new_eq_ge", "rel_old_eq_ge", "rel_new_eq_re", "rel_old_eq_re", "gap1_e", "gap2_e", "conf_rel", "conf_unrel", "dup_e", "viol"]
B1O_N = ["m0_solution_e", "rel_old_eq_se", "nwrong"]
H_DIM = 24 * 7 + 8
HO_DIM = 24 + 4


def state_features(h, g, sol, nwrong, E, masks, U, lm, strict=True):
    """One state's features for its 12 masks x 4 evaluation cells, rows in (mask index = dose*4 + mask, cell) order.
    h (9 digit fields, 81 cells, w) slow state; g displayed digits (1..9); sol solution digits; masks [(dose, mask, cells)]; U (w, k) frozen basis."""
    h64 = h.astype(np.float64); sc0 = np.einsum("fsw,w->sf", h64, lm); Z = np.einsum("fsw,wk->fsk", h64, U); order = np.argsort(-sc0, 1)
    mism = int((order[:, 0] + 1 != g).sum()); assert not strict or mism == 0, "displayed digits differ from the state's readout"
    r2, r3 = order[:, 1], order[:, 2]; viol = violations(g); cells = np.arange(81)
    gdisp = Z[g - 1, cells].mean(0); gall = Z.mean((0, 1))
    B0, B1, B1O, H, HO, BIL = [], [], [], [], [], []
    for (i, m, C) in masks:
        C = np.asarray(C, int); a, b = g[C], sol[C]; Za, Zb = Z[a - 1, C], Z[b - 1, C]; dZ = Zb - Za; confc = sc0[C, a - 1] - sc0[C, b - 1]; dzn = np.linalg.norm(dZ, axis=1).mean()
        for e in E:
            rel, rw, cl, bx = REL[e, C], ROW[e, C], COL[e, C], BOX[e, C]; ge, re_, se = g[e], r2[e] + 1, sol[e]; ur = ~rel
            B0.append([i == 0, i == 1, i == 2, len(C), rw.sum(), cl.sum(), bx.sum(), rel.sum(), ur.sum()])
            dup = int(((g == ge) & REL[e]).sum())
            B1.append([((b == ge) & rel).sum(), ((a == ge) & rel).sum(), ((b == re_) & rel).sum(), ((a == re_) & rel).sum(),
                       sc0[e, ge - 1] - sc0[e, r2[e]], sc0[e, r2[e]] - sc0[e, r3[e]], confc[rel].mean() if rel.any() else 0.0, confc[ur].mean() if ur.any() else 0.0, dup, viol])
            others = np.delete(sc0[e], se - 1); B1O.append([sc0[e, se - 1] - others.max(), ((a == se) & rel).sum(), nwrong])
            ze, zbar, zs = Z[ge - 1, e], Z[:, e].mean(0), Z[se - 1, e]
            dzr = dZ[rel].mean(0) if rel.any() else np.zeros(Z.shape[-1]); dzu = dZ[ur].mean(0) if ur.any() else np.zeros(Z.shape[-1])
            ips = [(Zb[rel] @ ze).sum(), (Za[rel] @ ze).sum(), (Zb[ur] @ ze).sum(), (Za[ur] @ ze).sum(), (dZ[rel] @ zbar).sum(), (dZ[ur] @ zbar).sum(), np.linalg.norm(ze), dzn]
            H.append(np.concatenate([ze, zbar, dzr, dzu, gdisp, gall, ze * rel.sum(), ips]))
            HO.append(np.concatenate([zs, [(Zb[rel] @ zs).sum(), (Za[rel] @ zs).sum(), (Zb[ur] @ zs).sum(), (Za[ur] @ zs).sum()]]))
            BIL.append(np.outer(ze, dZ[rel].sum(0) if rel.any() else np.zeros(Z.shape[-1])).ravel())
    f = lambda x: np.asarray(x, np.float64)
    return dict(B0=f(B0), B1=f(B1), B1O=f(B1O), H=f(H), HO=f(HO), BIL=f(BIL).astype(np.float32)), mism


# ---------------- replay (JAX environment) ----------------
def margins_from(arch, conds_wanted):
    """Per (state, condition, arm 0..12 [0 = no edit, 1 + dose*4 + mask], k, cell): the evaluation cell's solution-digit margin, from the archive."""
    d = np.load(arch, allow_pickle=False); conds = [str(x) for x in d["conds"]]; S = len(d["state_pid"]); K = d["escores"].shape[1]
    M = np.full((S, len(conds_wanted), 1 + ND * NM, K, NE), np.nan)
    sol = d["state_sol"].astype(int); E = d["state_E"].astype(int)
    for v in range(len(d["var_state"])):
        c = conds[int(d["var_cond"][v])]
        if c not in conds_wanted: continue
        s = int(d["var_state"][v]); arm = 0 if d["var_arm"][v] == 0 else 1 + int(d["var_dose"][v]) * NM + int(d["var_mask"][v]); esc = d["escores"][v].astype(np.float64)
        se = sol[s, E[s]] - 1; lab = esc[:, np.arange(NE), se]; oth = esc.copy(); oth[:, np.arange(NE), se] = -np.inf
        M[s, conds_wanted.index(c), arm] = lab - oth.max(-1)
    assert not np.isnan(M).any(); return M


def replay(out=OUT, smoke=False):
    import rebuttal_p26 as T26, rebuttal_p27 as T27, rebuttal_p16 as R16
    out.mkdir(parents=True, exist_ok=True); SCRATCH.mkdir(parents=True, exist_ok=True); prov = {}; t_all = time.time()

    def check_and_features(name, runner, prs, xcan, use, U, conds):
        d = np.load(ARCH[name], allow_pickle=False); lm = runner.lm; t0 = time.time()
        states = [(pr, di) for pr in prs if pr["pid"] in use for di in (0, 1)]
        if smoke: states = states[:4]
        nS = len(states) if smoke else len(d["state_pid"]); assert smoke or len(states) == nS, (name, len(states), nS)
        aconds = [str(x) for x in d["conds"]]; g = dict(pid=0, dir=0, E=0, grid=0, sol=0, masks=0); hyb_disp = 0
        vidx = {(int(d["var_state"][v]), aconds[int(d["var_cond"][v])], int(d["var_arm"][v]), int(d["var_dose"][v]), int(d["var_mask"][v])): v for v in range(len(d["var_state"]))}
        feats = {c: {k: [] for k in ("B0", "B1", "B1O", "H", "HO", "BIL")} for c in conds}
        for s, (pr, di) in enumerate(states):
            r = 0 if di == 0 else 1
            g["pid"] += int(d["state_pid"][s] != pr["pid"]); g["dir"] += int(d["state_dir"][s] != di); g["E"] += int(not np.array_equal(d["state_E"][s], pr["E"]))
            g["grid"] += int(not np.array_equal(d["state_grid"][s], pr["grid"][r])); g["sol"] += int(not np.array_equal(d["state_sol"][s], pr["sol"]))
            for (i, m, C) in pr["masks"]:
                v = vidx[(s, "intact", 1, i, m)]; saved = d["var_cells"][v]; g["masks"] += int(not np.array_equal(saved[saved >= 0], np.asarray(C)))
            hs = {"intact": pr["h"][r]} if conds == ["intact"] else (runner.condition_states(pr, di, U)[0] if name == "P27" else None)
            for c in conds:
                h = hs[c]; ft, mm = state_features(h, pr["grid"][r].astype(int), pr["sol"].astype(int), len(pr["W"][r]), pr["E"], pr["masks"], U, lm, strict=(c == "intact")); hyb_disp += mm
                for k in ft: feats[c][k].append(ft[k])
        prov[name] = dict(states=len(states), mismatches=g, hybrid_display_cells_differing=hyb_disp, seconds_features=round(time.time() - t0, 1))
        assert all(v == 0 for v in g.values()), f"provenance gate failed for {name}: {g}"
        # re-roll a sample through the archive's own rollout: the no-edit arm and mask 0 of each dose for the first two pair-directions
        specs, want = [], []
        for s, (pr, di) in enumerate(states[:2]):
            r = 0 if di == 0 else 1
            for (arm, i, m, C) in [(0, -1, -1, [])] + [(1, i, 0, C) for (i, m_, C) in pr["masks"] if m_ == 0]:
                specs.append(dict(b=pr["b"], h=pr["h"][r], l=pr["l"][r], grid=pr["grid"][r], sol=pr["sol"], cells=np.asarray(C, int))); want.append((s, arm, i, m, pr["E"]))

        def build(sp):
            h, l = sp["h"], sp["l"]
            for c in sp["cells"]: h, l = R16.cell_relabel(h, l, int(c), int(sp["grid"][c]), int(sp["sol"][c]))
            return h, l
        sc = runner.roll_variants(specs, xcan, None, build, f"p32check_{name}", [0]); dev = 0.0; bit = True
        for q, (s, arm, i, m, E) in enumerate(want):
            v = vidx[(s, "intact", arm, i, m)]; a = sc[q][:, E]; b = d["escores"][v]; dev = max(dev, float(np.abs(a - b).max())); bit &= bool(np.array_equal(a, b))
        prov[name].update(reroll_variants=len(specs), reroll_bitwise=bit, reroll_maxdev=dev)
        print(json.dumps({name: prov[name]}), flush=True)
        for c in conds:
            np.savez_compressed(out / f"p32_features_{name}_{c}{'_smoke' if smoke else ''}.npz", **{k: np.concatenate(v) for k, v in feats[c].items()},
                                state_pid=np.array([pr["pid"] for pr, _ in states], np.int64), state_dir=np.array([di for _, di in states], np.int8), meta=json.dumps(dict(prov[name], cond=c)))

    r26 = T26.R20p26(WIDTH, out=SCRATCH / "p26")
    prs, xcan = r26.pairs(smoke); disc, conf = T26.split([p["pid"] for p in prs], WIDTH); U = T27.load_basis(WIDTH, r26.lm)
    for name, use in (("P26D", disc), ("P26C", conf)): check_and_features(name, r26, prs, xcan, use, U, ["intact"])
    del prs, xcan
    r27 = T27.R21(WIDTH, out=SCRATCH / "p27"); prs, xcan = r27.pairs(smoke)
    check_and_features("P27", r27, prs, xcan, set(p["pid"] for p in prs), U, ["intact"] + list(HYBRIDS))
    (out / f"p32_replay_provenance{'_smoke' if smoke else ''}.json").write_text(json.dumps(dict(prov, wall_s=round(time.time() - t_all, 1)), indent=1) + "\n")


# ---------------- analysis (numpy) ----------------
def ridge_fit(X, y, lam, intercept):
    """Standardized ridge (features scaled by their training SD; constant columns dropped); returns a predictor."""
    sd = X.std(0); keep = sd > 1e-12; mu = X.mean(0) if intercept else np.zeros(X.shape[1]); Z = (X[:, keep] - mu[keep]) / sd[keep]
    y0 = y.mean() if intercept else 0.0; beta = np.linalg.solve(Z.T @ Z + lam * np.eye(Z.shape[1]), Z.T @ (y - y0))
    return lambda Xn: ((Xn[:, keep] - mu[keep]) / sd[keep]) @ beta + y0


def two_part(Xd, Yd):
    """Xd (S, dose, cell, mask, p), Yd (S, dose, cell, mask) -> level rows (dose-mean) and specific rows (within-dose centered over the 4 masks)."""
    Xl, yl = Xd.mean(3), Yd.mean(3); Xs = Xd - Xd.mean(3, keepdims=True); ys = Yd - Yd.mean(3, keepdims=True)
    return Xl.reshape(-1, Xd.shape[-1]), yl.reshape(-1), Xs.reshape(-1, Xd.shape[-1]), ys.reshape(-1)


def choose_lambda(Xd, Yd, puz, val_ok, seed):
    """Inner puzzle-grouped CV: the ridge strengths for the level and the specific parts (validation folds exclude the training-only puzzles)."""
    up = np.unique(puz[val_ok]); perm = np.random.default_rng(seed).permutation(len(up)); fold = {p: i % INNER for i, p in enumerate(up[perm])}
    fs = np.array([fold.get(p, -1) for p in puz]); err = {"L": np.zeros(len(LAMBDAS)), "S": np.zeros(len(LAMBDAS))}
    for f in range(INNER):
        tr, va = fs != f, fs == f
        if not va.any(): continue
        a = two_part(Xd[tr], Yd[tr]); b = two_part(Xd[va], Yd[va])
        for li, lam in enumerate(LAMBDAS):
            err["L"][li] += ((ridge_fit(a[0], a[1], lam, True)(b[0]) - b[1]) ** 2).sum(); err["S"][li] += ((ridge_fit(a[2], a[3], lam, False)(b[2]) - b[3]) ** 2).sum()
    return LAMBDAS[int(np.argmin(err["L"]))], LAMBDAS[int(np.argmin(err["S"]))]


def predict(fitL, fitS, Xd, p):
    Lp = fitL(Xd.mean(3).reshape(-1, p)).reshape(Xd.shape[:3]); Sp = fitS((Xd - Xd.mean(3, keepdims=True)).reshape(-1, p)).reshape(Xd.shape[:4]); return Lp, Sp


def calib_gain(Lp, Sp, Yd, tau):
    """Per (state, cell): the gain on the specific part from the three probes (mask PROBE of each dose), shrunk toward 1 with prior strength tau."""
    dev = Yd[:, :, :, PROBE] - Lp; sp = Sp[:, :, :, PROBE]; return (np.einsum("sic,sic->sc", dev, sp) + tau) / (np.einsum("sic,sic->sc", sp, sp) + tau)


def unmeasured_centered(A):
    U_ = np.delete(A, PROBE, axis=3); return U_ - U_.mean(3, keepdims=True)


def load_block(names, cond, blocks):
    out = []
    for nm in names:
        d = np.load(OUT / f"p32_features_{nm}_{cond}.npz", allow_pickle=False); out.append(np.concatenate([d[b] for b in blocks], 1).astype(np.float64))
    return np.concatenate(out, 0)


FAM = {"B0": ["B0"], "B1": ["B0", "B1"], "B1o": ["B0", "B1", "B1O"], "M3": ["B0", "B1", "H"], "M3o": ["B0", "B1", "B1O", "H", "HO"], "M3b": ["B0", "B1", "H", "BIL"]}


def analyze(k=0):
    names = ["P26D", "P26C", "P27"]; meta = {}; S_of = {}
    for nm in names:
        d = np.load(OUT / f"p32_features_{nm}_intact.npz", allow_pickle=False); S_of[nm] = len(d["state_pid"]); meta[nm] = (d["state_pid"], d["state_dir"])
    puz = np.concatenate([meta[nm][0] for nm in names]); arch = np.concatenate([[nm] * S_of[nm] for nm in names]); S = len(puz)
    Mi = {nm: margins_from(ARCH[nm], ["intact"]) for nm in names}
    Y = np.concatenate([(Mi[nm][:, 0, 1:, k] - Mi[nm][:, 0, :1, k]) for nm in names])                 # (S, 12 masks, cells): Delta at update k+1
    Yd = Y.reshape(S, ND, NM, NE).transpose(0, 1, 3, 2)                                                  # (S, dose, cell, mask)
    train_only = arch == "P26D"; scored = ~train_only
    up = np.unique(puz[scored]); perm = np.random.default_rng([SEED, 1]).permutation(len(up)); ofold = {p: i % OUTER for i, p in enumerate(up[perm])}
    of = np.array([ofold.get(p, -1) for p in puz])
    partner = np.array([np.where((puz == puz[s]) & (arch == arch[s]) & (np.arange(S) != s))[0][0] for s in range(S)])
    T_obs = unmeasured_centered(Yd); ok = np.sqrt((T_obs ** 2).mean(3)) >= RMS_MIN                          # (S, dose, cell)
    res = {"excluded_groups": int((~ok & scored[:, None, None]).sum()), "scored_groups": int((ok & scored[:, None, None]).sum())}
    preds = {}; sse = {}; sse_unc = {}; sse_all = {}
    for fam, blocks in FAM.items():
        X = load_block(names, "intact", blocks); p = X.shape[1]; Xd = X.reshape(S, ND, NM, NE, p).transpose(0, 1, 3, 2, 4)
        T_pred = np.zeros_like(T_obs); T_unc = np.zeros_like(T_obs); D_pred = np.zeros_like(np.delete(Yd, PROBE, 3)); lams = []
        for f in range(OUTER):
            tr, te = of != f, of == f                                                                  # training includes the training-only puzzles (of = -1)
            lamL, lamS = choose_lambda(Xd[tr], Yd[tr], puz[tr], ~train_only[tr], [SEED, 2, f, len(fam)]); lams.append((lamL, lamS))
            a = two_part(Xd[tr], Yd[tr]); fitL, fitS = ridge_fit(a[0], a[1], lamL, True), ridge_fit(a[2], a[3], lamS, False)
            Lt, St = predict(fitL, fitS, Xd[tr], p); tau = float(np.median(np.einsum("sic,sic->sc", St[:, :, :, PROBE], St[:, :, :, PROBE])))
            Lp, Sp = predict(fitL, fitS, Xd[te], p); gn = calib_gain(Lp, Sp, Yd[te], tau)
            T_pred[te] = gn[:, None, :, None] * unmeasured_centered(Sp); T_unc[te] = unmeasured_centered(Sp)
            D_pred[te] = Lp[..., None] + gn[:, None, :, None] * np.delete(Sp, PROBE, 3)
            preds.setdefault(fam, {})[f] = (fitL, fitS, tau)
        e = ((T_obs - T_pred) ** 2).sum(3) * ok; eu = ((T_obs - T_unc) ** 2).sum(3) * ok; ea = ((np.delete(Yd, PROBE, 3) - D_pred) ** 2).sum(3)
        sse[fam] = {pp: float(e[(puz == pp)].sum()) for pp in up}; sse_unc[fam] = float(eu[scored].sum()); sse_all[fam] = float(ea[scored].sum())
        res[fam] = dict(sse=float(sum(sse[fam].values())), sse_uncalibrated=sse_unc[fam], sse_overall_delta=sse_all[fam], lambdas=sorted(set(lams)))
    # the rollout-assisted reference: the other history's measured centered responses to the same masks, times a training-fitted gain
    sse["Rother"] = {}; To = T_obs[partner]
    for f in range(OUTER):
        tr, te = (of != f) & ok.all((1, 2)), of == f; gm = float((T_obs[tr] * To[tr]).sum() / max((To[tr] ** 2).sum(), 1e-300))
        e = ((T_obs[te] - gm * To[te]) ** 2).sum(3) * ok[te]
        for pp in np.unique(puz[te]): sse["Rother"][pp] = float(e[puz[te] == pp].sum())
    res["Rother"] = dict(sse=float(sum(sse["Rother"].values())), note="rollout-assisted: needs the other history's rollouts of the unmeasured masks")
    res["sse_zero"] = float(((T_obs ** 2).sum(3) * ok)[scored].sum())
    # the Stage-1 rule
    rng = np.random.default_rng([SEED, 3]); draws = [rng.choice(up, len(up)) for _ in range(NB)]
    def reduction(a, b):
        pt = 1 - sum(sse[a].values()) / sum(sse[b].values()); bs = [1 - sum(sse[a][q] for q in dr) / sum(sse[b][q] for q in dr) for dr in draws]
        return dict(point=float(pt), ci=(float(np.percentile(bs, 2.5)), float(np.percentile(bs, 97.5))))
    best_free = min(("B0", "B1"), key=lambda x: res[x]["sse"]); best_or = min(("B0", "B1", "B1o"), key=lambda x: res[x]["sse"])
    res["M3_vs_best_free"] = dict(baseline=best_free, **reduction("M3", best_free)); res["M3o_vs_best_oracle"] = dict(baseline=best_or, **reduction("M3o", best_or))
    res["M3b_vs_best_free"] = dict(baseline=best_free, **reduction("M3b", best_free)); res["Rother_vs_best_free"] = dict(baseline=best_free, **reduction("Rother", best_free))
    q = lambda r_: r_["point"] >= 0.10 and r_["ci"][0] > 0
    res["rule"] = dict(M3_qualifies=q(res["M3_vs_best_free"]), M3o_qualifies=q(res["M3o_vs_best_oracle"]))
    res["stage2_candidate"] = "M3 (oracle-free)" if res["rule"]["M3_qualifies"] else ("M3o (oracle-assisted)" if res["rule"]["M3o_qualifies"] else "none: no compact predictive description of correction-specific responses at this level")
    # the Stage-3 prototype on P27's hybrids (intact-trained models; the intact recipient's probe calibration)
    proto = {}
    Mh = margins_from(ARCH["P27"], ["intact"] + list(HYBRIDS)); i27 = np.where(arch == "P27")[0]; Yh = (Mh[:, :, 1:, k] - Mh[:, :, :1, k]).reshape(len(i27), 1 + len(HYBRIDS), ND, NM, NE).transpose(0, 1, 2, 4, 3)
    for fam in ("M3", "M3o"):
        Xi = load_block(["P27"], "intact", FAM[fam]); p = Xi.shape[1]; Xid = Xi.reshape(len(i27), ND, NM, NE, p).transpose(0, 1, 3, 2, 4); out = {}
        Xh = {c: load_block(["P27"], c, FAM[fam]).reshape(len(i27), ND, NM, NE, p).transpose(0, 1, 3, 2, 4) for c in HYBRIDS}
        pc = {c: np.zeros((len(i27), ND, NE, NM - 1)) for c in HYBRIDS}; oc = {c: np.zeros_like(pc[c]) for c in HYBRIDS}
        for f in range(OUTER):
            te = of[i27] == f
            if not te.any(): continue
            fitL, fitS, tau = preds[fam][f]; Lp, Sp = predict(fitL, fitS, Xid[te], p); gn = calib_gain(Lp, Sp, Yh[te, 0], tau)
            base = Lp[..., None] + gn[:, None, :, None] * np.delete(Sp, PROBE, 3)
            for ci, c in enumerate(HYBRIDS):
                Lc, Sc = predict(fitL, fitS, Xh[c][te], p); pc[c][te] = (Lc[..., None] + gn[:, None, :, None] * np.delete(Sc, PROBE, 3)) - base
                oc[c][te] = np.delete(Yh[te, 1 + ci], PROBE, 3) - np.delete(Yh[te, 0], PROBE, 3)
        for c in HYBRIDS:
            pr_, ob = pc[c].ravel(), oc[c].ravel(); out[c] = dict(reduction_vs_zero=float(1 - ((ob - pr_) ** 2).sum() / (ob ** 2).sum()), slope=float((pr_ @ ob) / max(pr_ @ pr_, 1e-300)),
                                                              corr=float(np.corrcoef(pr_, ob)[0, 1]), pred_rms=float(np.sqrt((pr_ ** 2).mean())), obs_rms=float(np.sqrt((ob ** 2).mean())))
        for (a_, b_) in (("lead", "lead_ctrl"), ("full", "comb_ctrl"), ("full", "full_random")):
            pr_, ob = (pc[a_] - pc[b_]).ravel(), (oc[a_] - oc[b_]).ravel()
            out[f"{a_}-{b_}"] = dict(reduction_vs_zero=float(1 - ((ob - pr_) ** 2).sum() / (ob ** 2).sum()), slope=float((pr_ @ ob) / max(pr_ @ pr_, 1e-300)), corr=float(np.corrcoef(pr_, ob)[0, 1]))
        proto[fam] = out
    res["stage3_prototype"] = proto
    return res


def report(k=0):
    res = analyze(k); fm = lambda r_: f"{100 * r_['point']:+.1f} % [{100 * r_['ci'][0]:+.1f}, {100 * r_['ci'][1]:+.1f}]"
    L = [f"P32 STAGE 1 (EXPLORATORY; plan frozen before it ran): Attention 192, update k = {k + 1}; primary target = within-dose centered responses of the 3 unmeasured masks",
         f"scored groups {res['scored_groups']}, excluded for insufficient variation {res['excluded_groups']}; SSE of predicting zero {res['sse_zero']:.1f}"]
    for fam in FAM: L.append(f"  {fam:4s}: SSE {res[fam]['sse']:.1f} (uncalibrated {res[fam]['sse_uncalibrated']:.1f}); overall-Delta SSE {res[fam]['sse_overall_delta']:.1f}; lambdas {res[fam]['lambdas']}")
    L.append(f"  Rother (rollout-assisted reference): SSE {res['Rother']['sse']:.1f}")
    L += [f"  M3 vs {res['M3_vs_best_free']['baseline']} (oracle-free): error reduction {fm(res['M3_vs_best_free'])}",
          f"  M3o vs {res['M3o_vs_best_oracle']['baseline']} (oracle-assisted): {fm(res['M3o_vs_best_oracle'])}",
          f"  M3b (bilinear, exploratory) vs {res['M3b_vs_best_free']['baseline']}: {fm(res['M3b_vs_best_free'])} | Rother vs {res['Rother_vs_best_free']['baseline']}: {fm(res['Rother_vs_best_free'])}",
          f"  STAGE-1 RULE (>= 10 % and lower bound > 0): {res['rule']} -> Stage-2 candidate: {res['stage2_candidate']}"]
    for fam, o in res["stage3_prototype"].items():
        L.append(f"  Stage-3 prototype ({fam}, intact-trained, intact probe calibration; response change vs zero): " + "; ".join(f"{c} red {v['reduction_vs_zero']:+.3f} slope {v['slope']:+.2f} corr {v['corr']:+.3f}" for c, v in o.items()))
    tag = f"k{k + 1}"; (OUT / f"p32_stage1_{tag}.txt").write_text("\n".join(L) + "\n"); (OUT / f"p32_stage1_{tag}.json").write_text(json.dumps(res, indent=1, default=float)); print("\n".join(L))


def selftest():
    assert REL.sum(1).tolist() == [20] * 81 and violations(np.array([[(i * 3 + i // 3 + j) % 9 + 1 for j in range(9)] for i in range(9)]).ravel()) == 0
    rng = np.random.default_rng(0); S, p = 300, 6
    Xd = rng.normal(size=(S, ND, NE, NM, p)); beta_s = np.array([0.8, 0, 0, 0, 0, 0]); lev = rng.normal(size=(S, ND, NE))
    Yd = lev[..., None] + 0.5 * Xd[..., 1:2].mean(3) + (Xd - Xd.mean(3, keepdims=True)) @ beta_s + 0.1 * rng.normal(size=(S, ND, NE, NM))
    a = two_part(Xd[:200], Yd[:200]); fitL, fitS = ridge_fit(a[0], a[1], 1.0, True), ridge_fit(a[2], a[3], 1.0, False); Lp, Sp = predict(fitL, fitS, Xd[200:], p)
    T_obs = unmeasured_centered(Yd[200:]); e_model = ((T_obs - unmeasured_centered(Sp)) ** 2).sum(); e_zero = (T_obs ** 2).sum(); assert e_model < 0.1 * e_zero      # the specific part recovered
    gn = calib_gain(Lp, Sp, Yd[200:], tau=1.0); assert np.isfinite(gn).all() and abs(np.median(gn) - 1) < 0.3
    # a model whose features carry only level information cannot predict the within-dose differences
    Xb = np.repeat(Xd.mean(3, keepdims=True), NM, 3); a2 = two_part(Xb[:200], Yd[:200]); f2 = ridge_fit(a2[2], a2[3], 1.0, False); _, Sb = predict(ridge_fit(a2[0], a2[1], 1.0, True), f2, Xb[200:], p)
    assert np.allclose(unmeasured_centered(Sb), 0)
    print("selftest OK")


def main():
    ap = argparse.ArgumentParser(description=__doc__); ap.add_argument("action", nargs="?", choices=["replay", "analyze"]); ap.add_argument("--smoke", action="store_true")
    ap.add_argument("--k", type=int, default=1, help="update after the change (1 primary, 2 secondary)"); ap.add_argument("--selftest", action="store_true"); a = ap.parse_args()
    if a.selftest: selftest(); return
    if a.action == "replay": replay(OUT, a.smoke)
    elif a.action == "analyze": report(a.k - 1)
    else: ap.print_help()


if __name__ == "__main__":
    main()
